import pandas as pd
import numpy as np

# Load data
waste_df = pd.read_csv('chunks_csv/outlierr/2023_waste.csv')
adj_df = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Build symmetric adjacency dictionary
boroughs = set(waste_df['borough'])
adjacency = {b: set() for b in boroughs}
for _, row in adj_df.iterrows():
    b, n = row['borough'], row['neighbor']
    if b in adjacency and n in adjacency:
        adjacency[b].add(n)
        adjacency[n].add(b)

# Map borough to its waste value
waste_map = waste_df.set_index('borough')['Waste_value'].to_dict()

def compute_regression_and_z(S):
    # Compute neighbor means within S
    neighbor_mean = {}
    for b in S:
        neighs = adjacency[b] & S
        if neighs:
            neighbor_mean[b] = np.mean([waste_map[n] for n in neighs])
        else:
            neighbor_mean[b] = np.nan
    # Prepare DataFrame for regression
    df_s = pd.DataFrame({
        'borough': list(S),
        'Waste_value': [waste_map[b] for b in S],
        'neighbor_mean': [neighbor_mean[b] for b in S]
    })
    df_reg = df_s.dropna(subset=['neighbor_mean'])
    # Design matrix and response
    X = np.vstack([
        np.ones(len(df_reg)),
        df_reg['neighbor_mean'].values
    ]).T
    Y = df_reg['Waste_value'].values
    # OLS estimation
    beta, residuals, *_ = np.linalg.lstsq(X, Y, rcond=None)
    a, b = beta
    # Residual std dev (n-2 degrees of freedom)
    res = Y - X.dot(beta)
    sigma = np.sqrt(np.sum(res**2) / (len(Y) - 2))
    # Compute standardized residuals z
    z = {}
    for _, row in df_s.iterrows():
        if not np.isnan(row['neighbor_mean']):
            z[row['borough']] = (row['Waste_value'] - (a + b * row['neighbor_mean'])) / sigma
        else:
            z[row['borough']] = np.nan
    return a, b, sigma, z, len(df_reg)

# Iterative-R procedure
S = set(boroughs)
while True:
    a, b, sigma, z_vals, n_used = compute_regression_and_z(S)
    z_H = z_vals.get('Hillingdon', np.nan)
    # Find the most extreme other borough
    others = {br: abs(z) for br, z in z_vals.items() if br != 'Hillingdon' and not np.isnan(z)}
    if not others:
        break
    outlier_borough, max_z = max(others.items(), key=lambda item: item[1])
    if max_z > abs(z_H):
        S.remove(outlier_borough)
    else:
        break

# Final classification
threshold = 1.96
if z_H > threshold:
    verdict = 'OUTLIER - HIGH'
elif z_H < -threshold:
    verdict = 'OUTLIER - LOW'
else:
    verdict = 'NOT AN OUTLIER'

# Output results
print(f"data_points_used = {n_used}")
print(f"FINAL ANSWER: {verdict} (z = {z_H})")
